(function(){
'use strict';
const T=TruthTree,L=Logic,P=TREE_PROBLEMS,$=id=>document.getElementById(id),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={consistency:'일관성',validity:'타당성',tautology:'논리적 참',contradiction:'논리적 거짓',equivalence:'동치'},key='logicWorkshopTreesV1';
let data={drafts:{},solved:[],current:P[0].id},storageWarning='';try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw&&raw.drafts&&Array.isArray(raw.solved))data=raw;}catch{storageWarning='저장된 기록을 읽지 못했습니다. 이 세션에서 새로 연습할 수 있습니다.';}
let current=Math.max(0,P.findIndex(p=>p.id===data.current)),actions=[],state,selected=1,filter='all',mode='natural';
let solved=new Set(data.solved.filter(id=>P.some(p=>p.id===id)));
function message(text,error=false){$('treeFeedback').textContent=text;$('treeFeedback').className='tree-feedback '+(error?'error':'success');}
function persist(){const answers={verdict:$('treeAnswer').value,model:Object.fromEntries([...$('treeModel').querySelectorAll('select')].map(s=>[s.dataset.atom,s.value]))};data.drafts[P[current].id]={actions,selected,answers};data.current=P[current].id;data.solved=[...solved];try{localStorage.setItem(key,JSON.stringify(data));}catch{message('자동 저장을 사용할 수 없습니다. 현재 세션에서는 계속 연습할 수 있습니다.',true);}}
function list(){const ps=P.filter(p=>filter==='all'||p.kind===filter);$('treeList').innerHTML=ps.map(p=>`<button class="problem-item ${P.indexOf(p)===current?'chosen':''}" data-problem="${P.indexOf(p)}" aria-current="${P.indexOf(p)===current}"><span class="problem-index">${String(P.indexOf(p)+1).padStart(2,'0')}</span><span><span class="problem-name">${escape(p.title)}</span><span class="problem-meta">${escape(p.section)} · p.${p.page} · ${names[p.kind]}</span></span>${solved.has(p.id)?'<span class="completion" aria-label="완료">✓</span>':''}</button>`).join('');$('treeSolved').innerHTML=solved.size+'<span> / '+P.length+'</span>';$('treeProgress').style.width=(solved.size/P.length*100)+'%';}
function drawing(s,interactive=true){function node(n){const leaf=!n.children.length;return `<div class="tree-node"><div class="tree-segment ${interactive&&leaf&&n.id===selected?'tree-selected':''}">${n.lines.map(l=>`<div class="tree-formula"><span>${l.id}</span><b>${escape(L.format(l.a))}</b><small>${l.source?l.source+', ':''}${escape(l.rule)}</small></div>`).join('')}${leaf?(interactive?`<button type="button" class="branch-tag" data-branch="${n.id}" aria-pressed="${n.id===selected}">가지 ${n.id} · ${n.closed?'× 닫힘 ('+n.closed.join(',')+')':n.open?'○ 열림':'계속 분해'}</button>`:`<div class="branch-tag">가지 ${n.id} · ${n.closed?'× 닫힘 ('+n.closed.join(',')+')':n.open?'○ 열림':'미완성'}</div>`):''}</div>${leaf?'':'<div class="tree-children">'+n.children.map(node).join('')+'</div>'}</div>`;}return node(s.root);}
function renderTree(){const leaves=T.paths(state).map(path=>path.at(-1));if(!leaves.some(n=>n.id===selected))selected=leaves.find(n=>!n.closed&&!n.open)?.id||leaves[0].id;const b=T.branch(state,selected),inactive=!!(b.node.closed||b.node.open);$('treeCanvas').innerHTML=drawing(state);$('treeBranch').innerHTML=leaves.map(n=>`<option value="${n.id}">가지 ${n.id} · ${n.closed?'× 닫힘':n.open?'○ 열림':'미완성'}</option>`).join('');$('treeBranch').value=selected;
 $('treePath').innerHTML=b.lines.map(l=>`<div class="tree-path-line"><span>${l.id}</span><span>${escape(L.format(l.a))}</span><small>${b.used.has(l.id)?'✓ 분해 완료':T.decomposition(l.a)?'미분해':'단순 문장'}</small></div>`).join('');
 const prior=$('treeLine').value,pending=T.pending(b);$('treeLine').innerHTML='<option value="">분해할 줄 선택</option>'+pending.map(l=>`<option value="${l.id}">${l.id}. ${escape(L.format(l.a))}</option>`).join('');if(pending.some(l=>l.id===Number(prior)))$('treeLine').value=prior;
 $('treeExpand').querySelectorAll('input,select,button').forEach(e=>e.disabled=inactive||!pending.length);$('treeCloseForm').querySelectorAll('input,button').forEach(e=>e.disabled=inactive);$('treeUndo').disabled=!actions.length;list();}
function answerVisibility(){$('treeModelWrap').hidden=$('treeAnswer').value!=='open';$('treeModel').querySelectorAll('select').forEach(s=>s.required=$('treeAnswer').value==='open');}
function load(i){current=i;const p=P[i],draft=data.drafts[p.id];let warning='';actions=draft?.actions||[];try{state=T.replay(p,actions);}catch{actions=[];state=T.initial(p);warning='저장된 풀이가 유효하지 않아 이 문제를 처음부터 열었습니다.';}selected=Number(draft?.selected)||1;
 $('treeKind').textContent=names[p.kind];$('treeNumber').textContent=(i+1)+' / '+P.length;$('treeTitle').textContent=p.title;
 $('treeQuestion').textContent={consistency:'이 문장들의 집합은 일관적인가?',validity:'이 논증은 타당한가? 타당하지 않으면 반례를 제시하세요.',tautology:'이 문장은 논리적 참인가?',contradiction:'이 문장은 논리적 거짓인가?',equivalence:'두 문장은 논리적으로 동치인가?'}[p.kind];
 const fs=p.kind==='validity'?[...p.premises]:p.formula?[p.formula]:p.formulas;$('treeStatement').textContent=fs.map(f=>L.format(L.parse(f))).join(p.kind==='equivalence'?'  /  ':', ')+(p.goal?' ∴ '+L.format(L.parse(p.goal)):'');
 $('treeSetup').textContent={consistency:'시작 집합: 주어진 문장들을 모두 SM으로 놓습니다.',validity:'시작 집합: 전제들과 결론의 부정. 열린 가지는 전제가 모두 참이고 결론이 거짓인 반례입니다.',tautology:'시작 집합: 주어진 문장의 부정. 모든 가지가 닫히면 원래 문장은 논리적 참입니다.',contradiction:'시작 집합: 주어진 문장 자체. 모든 가지가 닫히면 원래 문장은 논리적 거짓입니다.',equivalence:'시작 집합: 두 문장의 쌍조건문을 부정합니다. 열린 가지는 두 문장의 진리값이 다른 경우입니다.'}[p.kind];
 $('treeSource').href='sources/handout-6.pdf#page='+p.page;$('treeSource').textContent='핸드아웃 6 · '+p.section+' · p.'+p.page+' ↗';$('treeNote').textContent=p.note;
 const labels=T.labels(p);$('treeAnswer').innerHTML='<option value="">판정 선택</option><option value="open">'+labels[0]+'</option><option value="closed">'+labels[1]+'</option>';
 $('treeModelPrompt').textContent=p.kind==='consistency'?'열린 가지에서 문장들을 모두 참으로 만드는 진리값을 입력하세요.':p.kind==='contradiction'?'원래 문장을 참으로 만드는 진리값을 입력하세요.':'열린 가지의 반례가 되는 진리값을 입력하세요.';
 $('treeModel').innerHTML=T.variables(p).map(v=>`<label>${escape(v)}<select data-atom="${escape(v)}" aria-label="${escape(v)}의 진리값"><option value="">선택</option><option value="T">T · 참</option><option value="F">F · 거짓</option></select></label>`).join('');
 if(draft?.answers){$('treeAnswer').value=draft.answers.verdict||'';for(const el of $('treeModel').querySelectorAll('select'))el.value=draft.answers.model?.[el.dataset.atom]||'';}
 $('treeLeft').value='';$('treeRight').value='';$('treeCloseRefs').value='';$('treeRule').value='';$('treeHelp').textContent='';$('treeFeedback').textContent='';$('treeFeedback').className='tree-feedback';answerVisibility();renderTree();persist();if(warning||storageWarning)message(warning||storageWarning,true);
}
function act(action){try{const next=T.apply(state,action);actions.push(action);state=next;if(action.type==='expand'){$('treeLeft').value='';$('treeRight').value='';$('treeRule').value='';}renderTree();persist();message(action.type==='expand'?'✓ 올바른 분해입니다. 선택한 가지에 반영했습니다.':action.type==='close'?'× 모순을 확인하고 가지를 닫았습니다.':'○ 완전히 분해된 열린 가지입니다. 아래에서 판정과 진리값을 제출하세요.');}catch(e){message(e.message,true);}}
$('treeRule').insertAdjacentHTML('beforeend',T.rules.map(r=>`<option value="${escape(r[0])}">${escape(r[0])} · ${r[1]}</option>`).join(''));
$('treeExpand').onsubmit=e=>{e.preventDefault();act({type:'expand',branch:selected,line:Number($('treeLine').value),rule:$('treeRule').value,left:$('treeLeft').value,right:$('treeRight').value});};
$('treeCloseForm').onsubmit=e=>{e.preventDefault();act({type:'close',branch:selected,refs:$('treeCloseRefs').value});};$('treeOpen').onclick=()=>act({type:'open',branch:selected});
$('treeBranch').onchange=e=>{selected=Number(e.target.value);renderTree();persist();};$('treeCanvas').onclick=e=>{const b=e.target.closest('[data-branch]');if(b){selected=Number(b.dataset.branch);renderTree();persist();}};
$('treeUndo').onclick=()=>{if(!actions.length)return;actions.pop();state=T.replay(P[current],actions);renderTree();persist();message('직전 작업을 되돌렸습니다.');};
$('treeReset').onclick=()=>{if(actions.length&&!confirm('이 문제의 진리나무와 입력한 판정을 지우고 다시 시작할까요?'))return;delete data.drafts[P[current].id];load(current);};
$('treeAnswer').onchange=()=>{answerVisibility();persist();};$('treeModel').onchange=persist;
$('treeAnswerForm').onsubmit=e=>{e.preventDefault();try{const m={};for(const s of $('treeModel').querySelectorAll('select'))if(s.value)m[s.dataset.atom]=s.value==='T';const result=T.check(P[current],state,$('treeAnswer').value,m);solved.add(P[current].id);list();persist();message('✓ 정답입니다: '+result+'. 진리나무와 진리값 검증을 통과했습니다.');}catch(e){message(e.message,true);}};
$('treeList').onclick=e=>{const b=e.target.closest('[data-problem]');if(b)load(Number(b.dataset.problem));};$('treeFilter').onchange=e=>{filter=e.target.value;list();};$('treeNext').onclick=()=>{const candidates=P.map((p,i)=>({p,i})).filter(x=>filter==='all'||x.p.kind===filter);const n=candidates.findIndex(x=>x.i===current);load(candidates[(n+1)%candidates.length].i);};
$('treeHint').onclick=()=>{const a=T.suggest(state);$('treeHelp').textContent=!a?'나무의 분해가 끝났습니다. 판정과 필요한 진리값을 제출하세요.':a.type==='close'?`가지 ${a.branch}의 ${a.refs}번 줄이 서로 모순입니다. 두 줄을 인용해 ×로 닫으세요.`:a.type==='open'?`가지 ${a.branch}에는 더 분해할 문장과 모순이 없습니다. ○로 표시할 수 있습니다.`:`가지 ${a.branch}의 ${a.line}번 줄에 ${a.rule} 규칙을 적용해 보세요. ${T.rules.find(r=>r[0]===a.rule)[4]?'두 가지로 나뉩니다.':'같은 가지에 이어 적습니다.'}`;};
$('treeSolution').onclick=()=>{const p=P[current],solution=T.solve(p),st=T.status(solution.state),open=T.paths(solution.state).find(path=>path.at(-1).open);let tail='모든 가지가 닫혔습니다.';if(open){const b=T.branch(solution.state,open.at(-1).id),m=T.model(p,b);tail='열린 가지 '+b.node.id+'의 진리값 예: '+Object.entries(m).map(([v,val])=>v+' = '+(val?'T':'F')).join(', ')+'.';}const steps=solution.actions.map((a,i)=>`<li>${i+1}. 가지 ${a.branch} · ${a.type==='expand'?escape(a.line+'번, '+a.rule+' → '+a.left+(a.right?' / '+a.right:'')):a.type==='close'?escape(a.refs+'번 모순 → ×'):'완전 분해, 모순 없음 → ○'}</li>`).join('');$('treeHelp').innerHTML='<b>예시 풀이 · '+T.labels(p)[st==='open'?0:1]+'</b><p>내 풀이와 완료 기록은 바뀌지 않습니다. 분해 순서는 달라도 됩니다.</p><div class="tree-scroll">'+drawing(solution.state,false)+'</div><p>'+escape(tail)+'</p><details><summary>분해 순서 보기</summary><ol class="tree-steps">'+steps+'</ol></details>';};
function switchMode(next,focus=false){mode=next;const tree=mode==='tree';$('naturalPanel').hidden=tree;$('treePanel').hidden=!tree;for(const [id,on] of [['practiceNav',!tree],['treeNav',tree]]){$(id).classList.toggle('active',on);$(id).setAttribute('aria-selected',String(on));$(id).tabIndex=on?0:-1;}$('rulesNav').querySelector('span').textContent=tree?'진리나무 규칙 안내':'추론 규칙 안내';if(focus)$(tree?'treeNav':'practiceNav').focus();}
$('practiceNav').onclick=()=>{switchMode('natural');window.history.replaceState(null,'','#natural');};$('treeNav').onclick=()=>{switchMode('tree');window.history.replaceState(null,'','#tree');};
$('methodTabs').onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'natural':e.key==='End'?'tree':mode==='tree'?'natural':'tree';switchMode(next,true);window.history.replaceState(null,'','#'+next);}};
$('rulesNav').onclick=()=>$(mode==='tree'?'treeRulesDialog':'rulesDialog').showModal();$('treeDialogClose').onclick=()=>$('treeRulesDialog').close();
window.addEventListener('hashchange',()=>switchMode(location.hash==='#tree'?'tree':'natural'));
load(current);switchMode(location.hash==='#tree'?'tree':'natural');
})();
